// <diletta-tab-item> — a INSTÂNCIA WEB de `design-system-tab-item`.
//
// No Figma são SEIS componentes que não são variantes: são rótulos diferentes.
// Aqui é um, e o rótulo é prop — trocar o respiro da aba custava seis edições.
const ESTADO = ['normal', 'ativo', 'desligada'];
const ALTURA = 48;

class DilettaTabItem extends HTMLElement {
  static observedAttributes = ['estado', 'rotulo'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get estado() {
    const v = this.getAttribute('estado');
    return ESTADO.includes(v) ? v : 'normal';
  }

  render() {
    const e = this.estado;
    const tinta = e === 'ativo' ? 'fg' : e === 'desligada' ? 'textDisabled' : 'textSecondary';

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; }
        .aba {
          box-sizing: border-box;
          height: ${ALTURA}px; padding: 0 12px;
          background: none; font: inherit; cursor: ${e === 'desligada' ? 'default' : 'pointer'};
          color: var(--cps-${tinta});
          /* A sublinha é do ITEM e existe só no ativo. Longhand, porque o atalho
             de borda apaga a cor que vem antes. */
          border-width: 0 0 2px; border-style: solid;
          border-color: ${e === 'ativo' ? 'var(--cps-primary)' : 'transparent'};
        }
        .aba:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: -3px; }
      </style>
      <button class="aba" part="aba" type="button" role="tab"
              aria-selected="${e === 'ativo'}"
              ${e === 'desligada' ? 'disabled aria-disabled="true"' : ''}
              tabindex="${e === 'ativo' ? 0 : -1}">${this.getAttribute('rotulo') || ''}</button>`;
  }
}

customElements.define('diletta-tab-item', DilettaTabItem);
export { DilettaTabItem, ALTURA };
